  calculateSkillsDemand() {
    const skillDemandMap = new Map();
    // Analyser les compétences requises dans les fiches de poste
    this.jobDescriptions.forEach(job => {
      job.requiredSkills?.forEach(reqSkill => {
        const skillName = reqSkill.skill?.name || `Skill ${reqSkill.skill_id}`;
        const skillId = reqSkill.skill_id;
        if (!skillDemandMap.has(skillName)) {
          skillDemandMap.set(skillName, {
            skill_id: skillId,
            count: 0
          });
        }
        skillDemandMap.get(skillName).count++;
      });
    });
    // Transformation
    const skills = Array.from(skillDemandMap.entries()).map(([skillName, data]) => ({
