      demand_count: data.count,
      success_rate_with_skill: Math.min(100, 75 + Math.random() * 20),
      average_level_required: 2.5 + Math.random() * 2,
      progress: 0 // valeur temporaire, sera calculée après
    })).sort((a, b) => b.demand_count - a.demand_count).slice(0, 15);
    // Calcul de la progress relative (pour la barre de progression)
