    // Attendre que les éléments canvas soient disponibles
    setTimeout(() => {
      if (this.activeTab === 'overview') {
        this.createTrendsChart();
      } else if (this.activeTab === 'departments') {
        this.createDepartmentChart();
      } else if (this.activeTab === 'skills') {
        this.createSkillsChart();
      } else if (this.activeTab === 'contracts') {
        this.createContractChart();
      }
    }, 200);
  }

  updateChartsData(): void {
    console.log('🔄 Mise à jour des données des graphiques...');

    if (this.activeTab === 'overview' && this.trendsChart) {
      this.updateTrendsChart();
    } else if (this.activeTab === 'departments' && this.departmentChart) {
      this.updateDepartmentChart();
    } else if (this.activeTab === 'skills' && this.skillsChart) {
      this.updateSkillsChart();
    } else if (this.activeTab === 'contracts' && this.contractChart) {
      this.updateContractChart();
    }
