  createContractChart(): void {
    if (this.contractChart) {
      this.contractChart.destroy();
      this.contractChart = null;
    }

    const ctx = this.contractChartRef?.nativeElement?.getContext('2d');
    if (ctx && this.contractStats.length > 0) {
      this.contractChart = new Chart(ctx, {
        type: 'doughnut',
        data: {
          labels: this.contractStats.map(c => c.contract_type),
          datasets: [{
            data: this.contractStats.map(c => c.total_applications),
            backgroundColor: [
              '#3B82F6', // CDI
              '#10B981', // CDD
              '#F59E0B', // Stage
              '#EF4444', // Freelance
              '#8B5CF6'  // Apprentissage
            ],
            borderWidth: 2,
            borderColor: '#ffffff'
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: {
              position: 'bottom'
            },
            tooltip: {
              callbacks: {
                label: (context) => {
                  const total = context.dataset.data.reduce((sum: any, current: any) => sum + current, 0);
                  const percentage = total > 0 ? ((context.parsed / total) * 100).toFixed(1) : 0;
                  return `${context.label}: ${context.parsed} (${percentage}%)`;
                }
              }
            }
          }
        }
      });
    }
  }

