  // ==================== GESTION DES FILTRES ====================

  applyFilters(): void {
    console.log('🔍 Application des filtres:', this.filters);

    // Filtrer les données selon les critères
    this.filterData();

    // Recalculer les analytics avec les données filtrées
    this.calculateRealAnalytics();

    // Mettre à jour les graphiques avec les nouvelles données
    this.updateChartsData();
  }

  filterData(): void {
    // Appliquer les filtres sur les données
    let filteredEmployees = [...this.employees];
    let filteredJobDescriptions = [...this.jobDescriptions];
    let filteredJobOffers = [...this.jobOffers];

    // Filtre par département
    if (this.filters.department) {
      filteredEmployees = filteredEmployees.filter(emp => 
        emp.department === this.filters.department || emp.position === this.filters.department
      );
      filteredJobDescriptions = filteredJobDescriptions.filter(job => 
        job.filiere_activite === this.filters.department
      );
    }

    // Filtre par type de contrat
    if (this.filters.contract_type) {
      filteredJobOffers = filteredJobOffers.filter(offer => 
        offer.contract_type === this.filters.contract_type
      );
    }

    // Filtre par dates
    if (this.filters.date_from) {
      const fromDate = new Date(this.filters.date_from);
      filteredJobOffers = filteredJobOffers.filter(offer => 
        new Date(offer.createdAt || '') >= fromDate
      );
    }

    if (this.filters.date_to) {
      const toDate = new Date(this.filters.date_to);
      filteredJobOffers = filteredJobOffers.filter(offer => 
        new Date(offer.createdAt || '') <= toDate
      );
    }

    // Mettre à jour les données filtrées (temporairement pour les calculs)
    const originalEmployees = this.employees;
    const originalJobDescriptions = this.jobDescriptions;
    const originalJobOffers = this.jobOffers;

    this.employees = filteredEmployees;
    this.jobDescriptions = filteredJobDescriptions;
    this.jobOffers = filteredJobOffers;

    // Les calculs utiliseront maintenant les données filtrées
    // Après les calculs, on restaurera les données originales
    setTimeout(() => {
      this.employees = originalEmployees;
      this.jobDescriptions = originalJobDescriptions;
      this.jobOffers = originalJobOffers;
    }, 100);
  }

  clearFilters(): void {
    console.log('🧹 Effacement des filtres');
    this.filters = {};
    this.calculateRealAnalytics();
    this.updateChartsData();
  }

  refreshData(): void {
    console.log('🔄 Actualisation manuelle des données...');
    this.loadRealData();
  }

  // ==================== EXPORT DES DONNÉES ====================

  exportAnalytics(): void {
    const csvData = this.generateAnalyticsCSV();
    const blob = new Blob([csvData], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `analytics-${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  generateAnalyticsCSV(): string {
    const headers = ['Département', 'Employés', 'Fiches de Poste', 'Offres d\'Emploi', 'Taux de Succès'];
    const rows = this.departmentStats.map(dept => [
      dept.department,
      this.employees.filter(emp => emp.department === dept.department || emp.position === dept.department).length,
      this.jobDescriptions.filter(job => job.filiere_activite === dept.department).length,
      dept.total_applications,
      `${dept.success_rate.toFixed(1)}%`
    ]);

    return [headers, ...rows].map(row => 
      row.map(cell => `"${cell}"`).join(',')
    ).join('\n');
  }

  // ==================== UTILITAIRES ====================

  getFilteredEmployeesCount(): number {
    if (!this.filters.department) return this.employees.length;
    return this.employees.filter(emp => 
      emp.department === this.filters.department || emp.position === this.filters.department
    ).length;
  }

  getFilteredJobOffersCount(): number {
    let count = this.jobOffers.length;

    if (this.filters.contract_type) {
      count = this.jobOffers.filter(offer => offer.contract_type === this.filters.contract_type).length;
    }

    return count;
  }

  getPublishedOffersCount(): number {
    return this.jobOffers.filter(offer => offer.status === 'published').length;
  }

  getAverageSkillsPerEmployee(): number {
    if (this.employees.length === 0) return 0;

    const totalSkills = this.employees.reduce((sum, emp) => {
      const skillsCount = emp.skills?.length || emp.EmployeeSkills?.length || 0;
      return sum + skillsCount;
    }, 0);

    return totalSkills / this.employees.length;
  }

  getCertifiedEmployeesCount(): number {
    return this.employees.filter(emp => {
      const skills = emp.skills || emp.EmployeeSkills || [];
      return skills.some(skill => skill.certification && skill.certification.trim() !== '');
    }).length;
  }

  getAverageExperienceYears(): number {
    if (this.employees.length === 0) return 0;

    const now = new Date();
    const totalYears = this.employees.reduce((sum, emp) => {
      const hireDate = new Date(emp.hire_date);
      const years = (now.getTime() - hireDate.getTime()) / (1000 * 60 * 60 * 24 * 365);
      return sum + years;
    }, 0);

    return totalYears / this.employees.length;
  }

  formatLastUpdate(): string {
    return this.lastDataUpdate.toLocaleTimeString('fr-FR', {
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  }
